function wornTiles(length, passes, limit) {
  const scrubbed = new Array(length).fill(0);
  for (const [from, to] of passes) {
    for (let tile = from; tile <= to; tile++) scrubbed[tile]++;
  }
  let worn = 0;
  for (let tile = 0; tile < length; tile++) {
    if (scrubbed[tile] >= limit) worn++;
  }
  return worn;
}

function wornTiles(length, passes, limit) {
  const opens = passes.map((pass) => pass[0]).sort((a, b) => a - b);
  const closes = passes.map((pass) => pass[1] + 1).sort((a, b) => a - b);
  let i = 0;
  let j = 0;
  let active = 0;
  let at = 0;
  let worn = 0;
  while (i < opens.length || j < closes.length) {
    const edge = j >= closes.length || (i < opens.length && opens[i] < closes[j]) ? opens[i] : closes[j];
    if (active >= limit) worn += edge - at;
    at = edge;
    while (i < opens.length && opens[i] === edge) {
      active++;
      i++;
    }
    while (j < closes.length && closes[j] === edge) {
      active--;
      j++;
    }
  }
  return worn;
}

function wornTiles(length, passes, limit) {
  const change = new Int32Array(length + 1);
  for (const [from, to] of passes) {
    change[from]++;
    change[to + 1]--;
  }
  let running = 0;
  let worn = 0;
  for (let tile = 0; tile < length; tile++) {
    running += change[tile];
    if (running >= limit) worn++;
  }
  return worn;
}
